import { Chart, Plugin } from 'chart.js';
import { theme } from 'theme';

const SLASH_TILT_PX = 6.06;
const SLASH_LENGTH_PX = 10.5;
const SLASH_GAP_PX = 6;
const SLASH_LINE_WIDTH = 1;
const DEFAULT_BREAK_COLOR = theme.colors.charts.border.neutrals[40];

export interface AxisBreakPluginOptions {
  indexes: number[];
  color?: string;
}

/**
 * Draws a double-slash axis-break marker (//) BETWEEN two adjacent bars,
 * anchored to the bottom of the chart area (`yScale.bottom`). Each entry in
 * `indexes` represents the bar index after which the marker should appear
 * (mark sits between bar `index` and bar `index + 1`). Used to visually
 * convey that a period was removed from the dataset (e.g. Q2/2020) rather
 * than being a real value.
 *
 * The baseline is `yScale.bottom` instead of `yScale.getPixelForValue(0)`
 * because charts that set `suggestedMin > 0` push the pixel of `value = 0`
 * outside the visible canvas, hiding the marker. `yScale.bottom` always
 * tracks the X-axis line, regardless of the y-axis domain. Falls back to
 * `getPixelForValue(0)` only when `bottom` is unavailable (e.g. older test
 * mocks).
 *
 * Slash dimensions are fixed (Figma: 6.06 x 10.5 px per slash, 1px stroke,
 * 6 px gap between the pair) so the marker keeps the same visual weight
 * regardless of bar/chart size — matches the static Figma reference.
 *
 * Options are read from `chart.options.plugins.axisBreak` on every redraw so
 * data/color changes always reflect the latest props.
 */
export const AxisBreakPlugin: Plugin<'bar'> = {
  id: 'axisBreak',
  afterDatasetsDraw(chart: Chart<'bar'>) {
    const pluginOpts = chart.options?.plugins?.axisBreak as
      | AxisBreakPluginOptions
      | undefined;

    if (!pluginOpts?.indexes?.length) return;

    const { indexes, color = DEFAULT_BREAK_COLOR } = pluginOpts;
    const { ctx, scales } = chart;
    const xScale = scales.x;
    const yScale = scales.y;

    if (!xScale || !yScale) return;

    const tilt = SLASH_TILT_PX;
    const length = SLASH_LENGTH_PX;
    const gap = SLASH_GAP_PX;
    const halfLength = length / 2;
    const halfTilt = tilt / 2;
    const halfGap = gap / 2;

    const yScaleBottom = (yScale as { bottom?: number }).bottom;
    const baselineY =
      typeof yScaleBottom === 'number'
        ? yScaleBottom
        : yScale.getPixelForValue(0);

    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = SLASH_LINE_WIDTH;
    ctx.lineCap = 'round';

    const drawSlash = (xBottom: number) => {
      ctx.beginPath();
      ctx.moveTo(xBottom, baselineY + halfLength);
      ctx.lineTo(xBottom + tilt, baselineY - halfLength);
      ctx.stroke();
    };

    indexes.forEach((index) => {
      const leftX = xScale.getPixelForValue(index);
      const rightX = xScale.getPixelForValue(index + 1);
      const centerX = (leftX + rightX) / 2;
      drawSlash(centerX - halfGap - halfTilt);
      drawSlash(centerX + halfGap - halfTilt);
    });

    ctx.restore();
  },
};
